entries[18634] = { ["name"] = "Gyrofrosteisreflektor", ["text"] = "Wird beim Anlegen gebunden\nSchmuck\n+15 Frostwiderstand\nBenötigt Stufe 47\nBenötigt Ingenieurskunst (260)\nBenutzen: Reflektiert 5 sec lang Frostzauber zurück auf den Zaubernden. Es besteht die Chance, dass dem Effekt widerstanden wird, wenn der Zaubernde über Stufe 60 ist. (5 Min Abklingzeit)" }
