entries[18637] = { ["name"] = "Großer Rekombobulator", ["text"] = "Schmuck\nBenötigt Ingenieurskunst (275)\nBenutzen: Stellt 375 to 625 Gesundheit und Mana eines freundlichen Ziels wieder her und versucht, jegliche Verwandlungseffekte auf ihm zu bannen. Verringerte Wirksamkeit gegen Verwandlungseffekte von Zaubernden der Stufe 61 und höher. (5 Min Abklingzeit)\n10 Aufladungen" }
entries[18638] = { ["name"] = "Hyperstrahlender Flammenreflektor", ["text"] = "Wird beim Anlegen gebunden\nSchmuck\n+18 Feuerwiderstand\nBenötigt Stufe 53\nBenötigt Ingenieurskunst (290)\nBenutzen: Reflektiert 5 sec lang Feuerzauber zurück auf den Zaubernden. Es besteht die Chance, dass dem Effekt widerstanden wird, wenn der Zaubernde über Stufe 60 ist. (5 Min Abklingzeit)" }
entries[18639] = { ["name"] = "Ultrablendender Schattenreflektor", ["text"] = "Wird beim Anlegen gebunden\nSchmuck\n+20 Schattenwiderstand\nBenötigt Stufe 55\nBenötigt Ingenieurskunst (300)\nBenutzen: Reflektiert 5 sec lang Schattenzauber zurück auf den Zaubernden. Es besteht die Chance, dass dem Effekt widerstanden wird, wenn der Zaubernde über Stufe 60 ist. (5 Min Abklingzeit)" }
entries[18640] = { ["name"] = "Lustiger Spaßstein", ["text"] = "Benutzen: Werft den Stein einem freundlich gesinnten Spieler zu. Wenn das Ziel einen freien Inventarplatz hat, wird es den Stein auffangen." }
entries[18641] = { ["name"] = "Dichtes Dynamit", ["text"] = "Benötigt Ingenieurskunst (250)\nBenutzen: Verursacht 340 to 460 Feuerschaden, in einem Radius von 5 m. (1 Min Abklingzeit)" }
entries[18642] = { ["name"] = "Jainas Autogramm", ["text"] = "Questgegenstand\nEinzigartig\n\"Sei stark, Randis, und strebe danach der Held zu werden, der dir vorherbestimmt wurde zu sein. -- Lady Jaina Prachtmeer\"" }
entries[18643] = { ["name"] = "Cairnes Hufabdruck", ["text"] = "Questgegenstand\nEinzigartig\n\"Höre auf die Geister, junger Grunz. Denn nur von ihnen erfährt der wahre Held seine Berufung. -- Cairne Bluthuf\"" }
entries[18645] = { ["name"] = "Gnomischer Alarm-o-Bot", ["text"] = "Benötigt Ingenieurskunst (265)\nBenutzen: Beschwört einen gnomischen Alarm-o-Bot, der die Umgebung nach getarnten Feinden scannt. Der Alarm-o-Bot kann gegebenenfalls falschen Alarm schlagen. Hält bis zu 2 min lang vor. (5 Min Abklingzeit)" }
entries[18646] = { ["name"] = "Das Auge der Offenbarung", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nSchmuck\nKlassen: Priester\nBenötigt Stufe 60\n\"Ihr könnt Bewegungen ausmachen, wenn ihr in das Auge blickt.\"\n<Zum Lesen rechtsklicken>" }
entries[18647] = { ["name"] = "Bauplan: Rotes Feuerwerk", ["text"] = "Benötigt Ingenieurskunst (150)\nBenutzen: Lehrt Euch die Herstellung von rotem Feuerwerk.\nRotes Feuerwerk\nBenutzen: Schießt ein Feuerwerk in die Luft, das in tausend rote Sterne explodiert.\nBenötigt Schweres Sprengpulver , Schweres Leder" }
entries[18648] = { ["name"] = "Bauplan: Grünes Feuerwerk", ["text"] = "Benötigt Ingenieurskunst (150)\nBenutzen: Lehrt Euch die Herstellung von grünem Feuerwerk.\nGrünes Feuerwerk\nBenutzen: Schießt ein Feuerwerk in die Luft, das in tausend grüne Sterne explodiert.\nBenötigt Schweres Sprengpulver , Schweres Leder" }
entries[18649] = { ["name"] = "Bauplan: Blaues Feuerwerk", ["text"] = "Benötigt Ingenieurskunst (150)\nBenutzen: Lehrt Euch die Herstellung von blauem Feuerwerk.\nBlaues Feuerwerk\nBenutzen: Schießt ein Feuerwerk in die Luft, das in tausend blaue Sterne explodiert.\nBenötigt Schweres Sprengpulver , Schweres Leder" }
entries[18650] = { ["name"] = "Bauplan: EZ-Thro-Dynamit II", ["text"] = "Benötigt Ingenieurskunst (200)\nBenutzen: Lehrt Euch die Herstellung von EZ-Thro-Dynamit II.\nEZ-Thro-Dynamit II\nBenötigt Stufe 30\nBenutzen: Fügt 213 to 287 Feuerschaden in einem Radius von 5 Metern zu (sollte es das Ziel treffen; es gelten Beschränkungen). (1 Min Abklingzeit)\n\"Das Dynamit für jedermann, das selten* in der Hand hochgeht, mit mehr als der doppelten Sprengkraft von einfachem EZ-Thro.\"\nBenötigt Robustes Sprengpulver , Magiestoff (2)" }
entries[18651] = { ["name"] = "Bauplan: Echtsilberumwandler", ["text"] = "Benötigt Ingenieurskunst (260)\nBenutzen: Lehrt Euch die Herstellung eines Echtsilberumwandlers.\nEchtsilberumwandler\nBenötigt Echtsilberbarren (2), Elementarerde (2), Elementarluft" }
entries[18652] = { ["name"] = "Bauplan: Gyrofrosteisreflektor", ["text"] = "Benötigt Ingenieurskunst (260)\nBenutzen: Lehrt Euch die Herstellung eines Gyrofrosteisreflektors.\nGyrofrosteisreflektor\nWird beim Anlegen gebunden\nSchmuck\n+15 Frostwiderstand\nBenötigt Stufe 47\nBenötigt Ingenieurskunst (260)\nBenutzen: Reflektiert 5 sec lang Frostzauber zurück auf den Zaubernden. Es besteht die Chance, dass dem Effekt widerstanden wird, wenn der Zaubernde über Stufe 60 ist. (5 Min Abklingzeit)\nBenötigt Thoriumapparat (6), Echtsilberumwandler (2), Blauer Saphir (2), Essenz des Feuers (4), Frostöl (2), Eiskappe (4)" }
entries[18653] = { ["name"] = "Bauplan: Goblinüberbrückungskabel XL", ["text"] = "Benötigt Ingenieurskunst (265)\nBenötigt Gobliningenieur\nBenutzen: Lehrt Euch die Herstellung von Goblinüberbrückungskabeln XL.\nGoblinüberbrückungskabel XL\nBenötigt Ingenieurskunst (265)\nBenutzen: Mit Überbrückungskabeln kann man manchmal einen toten Spieler ins Leben zurückrufen. Kann nicht im Kampf verwendet werden. (30 Min Abklingzeit)\nBenötigt Thoriumapparat (2), Echtsilberumwandler (2), Verschmorte Verkabelung (2), Eisenweberseide (2), Sternrubin (2)" }
entries[18654] = { ["name"] = "Bauplan: Gnomischer Alarm-o-Bot", ["text"] = "Benötigt Ingenieurskunst (265)\nBenötigt Gnomeningenieur\nBenutzen: Lehrt Euch die Herstellung eines Alarm-o-Bots.\nGnomischer Alarm-o-Bot\nBenötigt Ingenieurskunst (265)\nBenutzen: Beschwört einen gnomischen Alarm-o-Bot, der die Umgebung nach getarnten Feinden scannt. Der Alarm-o-Bot kann gegebenenfalls falschen Alarm schlagen. Hält bis zu 2 min lang vor. (5 Min Abklingzeit)\nBenötigt Thoriumbarren (4), Verschmorte Verkabelung" }
entries[18655] = { ["name"] = "Bauplan: Großer Rekombobulator", ["text"] = "Benötigt Ingenieurskunst (275)\nBenutzen: Lehrt Euch die Herstellung eines großen Rekombobulator.\nGroßer Rekombobulator\nSchmuck\nBenötigt Ingenieurskunst (275)\nBenutzen: Stellt 375 to 625 Gesundheit und Mana eines freundlichen Ziels wieder her und versucht, jegliche Verwandlungseffekte auf ihm zu bannen. Verringerte Wirksamkeit gegen Verwandlungseffekte von Zaubernden der Stufe 61 und höher. (5 Min Abklingzeit)\n10 AufladungenBenötigt Thoriumröhre (2), Echtsilberumwandler , Runenstoff (2)" }
entries[18656] = { ["name"] = "Bauplan: Mächtige Zephyriumladung", ["text"] = "Benötigt Ingenieurskunst (275)\nBenutzen: Lehrt Euch die Herstellung von mächtigen Zephyriumladungen.\nMächtige Zephyriumladung\nBenötigt Ingenieurskunst (275)\nBenutzen: Sprengt fast jede fest verschlossene Tür oder Truhe auf.\nBenötigt Thoriumapparat (2), Dichtes Sprengpulver (3), Unverwüstliches Leder (2), Erfrischendes Quellwasser" }
entries[18657] = { ["name"] = "Bauplan: Hyperstrahlender Flammenreflektor", ["text"] = "Benötigt Ingenieurskunst (290)\nBenutzen: Lehrt Euch die Herstellung eines hyperstrahlenden Flammenreflektors.\nHyperstrahlender Flammenreflektor\nWird beim Anlegen gebunden\nSchmuck\n+18 Feuerwiderstand\nBenötigt Stufe 53\nBenötigt Ingenieurskunst (290)\nBenutzen: Reflektiert 5 sec lang Feuerzauber zurück auf den Zaubernden. Es besteht die Chance, dass dem Effekt widerstanden wird, wenn der Zaubernde über Stufe 60 ist. (5 Min Abklingzeit)\nBenötigt Dunkeleisenbarren (4), Echtsilberumwandler (3), Essenz des Wassers (6), Sternrubin (4), Azerothischer Diamant (2)" }
entries[18658] = { ["name"] = "Bauplan: Ultrablendender Schattenreflektor", ["text"] = "Benötigt Ingenieurskunst (300)\nBenutzen: Lehrt Euch die Herstellung eines ultrablendenden Schattenreflektors.\nUltrablendender Schattenreflektor\nWird beim Anlegen gebunden\nSchmuck\n+20 Schattenwiderstand\nBenötigt Stufe 55\nBenötigt Ingenieurskunst (300)\nBenutzen: Reflektiert 5 sec lang Schattenzauber zurück auf den Zaubernden. Es besteht die Chance, dass dem Effekt widerstanden wird, wenn der Zaubernde über Stufe 60 ist. (5 Min Abklingzeit)\nBenötigt Dunkeleisenbarren (8), Echtsilberumwandler (4), Essenz des Lebens (6), Essenz des Untodes (4), Azerothischer Diamant (2), Großer Opal (2)" }
entries[18659] = { ["name"] = "Splitter von Nordrassil", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenötigt Stufe 60\nBenutzen: Formt eine Segnung wenn mit dem Auge der Schatten und dem Auge der Offenbarung kombiniert.\n\"Ein kleines Fragment des Weltenbaumes\"" }
entries[18660] = { ["name"] = "Weltvergrößerer", ["text"] = "Spielzeug\nBenötigt Ingenieurskunst (250)\nBenötigt Gnomeningenieur\nBenutzen: Vergrößert die gesamte Welt 5 min lang oder bis Ihr angreift. (15 Min Abklingzeit)\n\"Nur die Technologie der Gnome konnte ein Gerät erfinden, das die ganze Welt revolutionieren würde!\"" }
entries[18661] = { ["name"] = "Bauplan: Weltvergrößerer", ["text"] = "Benötigt Ingenieurskunst (260)\nBenötigt Gnomeningenieur\nBenutzen: Lehrt Euch die Herstellung eines Weltvergrößerers.\nWeltvergrößerer\nSpielzeug\nBenötigt Ingenieurskunst (250)\nBenötigt Gnomeningenieur\nBenutzen: Vergrößert die gesamte Welt 5 min lang oder bis Ihr angreift. (15 Min Abklingzeit)\n\"Nur die Technologie der Gnome konnte ein Gerät erfinden, das die ganze Welt revolutionieren würde!\"\nBenötigt Mithrilgehäuse , Thoriumapparat (2), Goldkraftkern , Instabiler Auslöser , Citrin" }
