entries[19237] = { ["name"] = "Sayges Horoskop Nr. 19", ["text"] = "Wird beim Aufheben gebunden\n\"Die Verlassenen haben etwas vor.\"" }
entries[19238] = { ["name"] = "Sayges Horoskop Nr. 3", ["text"] = "Wird beim Aufheben gebunden\n\"Ein früherer Gegner wird bald zu einem Verbündeten werden.\"" }
entries[19239] = { ["name"] = "Sayges Horoskop Nr. 4", ["text"] = "Wird beim Aufheben gebunden\n\"Ihr werdet bei allem ein glückliches Händchen haben.\"" }
entries[19240] = { ["name"] = "Sayges Horoskop Nr. 5", ["text"] = "Wird beim Aufheben gebunden\n\"Jemand spricht gut von Euch.\"" }
entries[19241] = { ["name"] = "Sayges Horoskop Nr. 6", ["text"] = "Wird beim Aufheben gebunden\n\"Seid vorsichtig, wenn Ihr in nicht vertrauten Gebieten landet.\"" }
entries[19242] = { ["name"] = "Sayges Horoskop Nr. 7", ["text"] = "Wird beim Aufheben gebunden\n\"Vermeidet unnötige Risiken.\"" }
entries[19243] = { ["name"] = "Sayges Horoskop Nr. 8", ["text"] = "Wird beim Aufheben gebunden\n\"Ihr werdet ein Vermögen erhalten.\"" }
entries[19244] = { ["name"] = "Sayges Horoskop Nr. 9", ["text"] = "Wird beim Aufheben gebunden\n\"Eure erste und letzte Liebe ist Eigenliebe.\"" }
entries[19245] = { ["name"] = "Sayges Horoskop Nr. 10", ["text"] = "Wird beim Aufheben gebunden\n\"Ruhe ist eine gute Sache, doch Langweile ist dessen Bruder.\"" }
entries[19246] = { ["name"] = "Sayges Horoskop Nr. 11", ["text"] = "Wird beim Aufheben gebunden\n\"Diejenigen, die einen einfachen Geschmack haben, sind immer mit dem Besten zufrieden.\"" }
entries[19247] = { ["name"] = "Sayges Horoskop Nr. 12", ["text"] = "Wird beim Aufheben gebunden\n\"Lasst Euch nicht von den Fluten des Krieges hinwegspülen.\"" }
entries[19248] = { ["name"] = "Sayges Horoskop Nr. 13", ["text"] = "Wird beim Aufheben gebunden\n\"Ihr macht Eure Gegner sprachlos.\"" }
entries[19249] = { ["name"] = "Sayges Horoskop Nr. 14", ["text"] = "Wird beim Aufheben gebunden\n\"Ihr habt einen guten Riecher für Heuchlerei.\"" }
entries[19250] = { ["name"] = "Sayges Horoskop Nr. 15", ["text"] = "Wird beim Aufheben gebunden\n\"So manch einer lernt mehr, wenn er andere unterrichtet.\"" }
entries[19251] = { ["name"] = "Sayges Horoskop Nr. 16", ["text"] = "Wird beim Aufheben gebunden\n\"Ihr werdet bald eine dringliche Entscheidung fällen müssen.\"" }
entries[19252] = { ["name"] = "Sayges Horoskop Nr. 18", ["text"] = "Wird beim Aufheben gebunden\n\"Nehmt den nächsten Vorschlag an, der Euch zu Ohren kommt.\"" }
entries[19253] = { ["name"] = "Sayges Horoskop Nr. 17", ["text"] = "Wird beim Aufheben gebunden\n\"Stoßt einen Gnom niemals grundlos an.\"" }
entries[19254] = { ["name"] = "Sayges Horoskop Nr. 21", ["text"] = "Wird beim Aufheben gebunden\n\"Gottesschilde und Ruhesteine machen einen Helden nicht heldenhaft.\"" }
entries[19255] = { ["name"] = "Sayges Horoskop Nr. 22", ["text"] = "Wird beim Aufheben gebunden\n\"Eine blaue Antwort ist immer eine schlaue Antwort.\"" }
entries[19256] = { ["name"] = "Sayges Horoskop Nr. 2", ["text"] = "Wird beim Aufheben gebunden\n\"Morgen werdet Ihr etwas Wunderschönes finden.\"" }
